//! Cargo lock validation and atomic compatibility projection.
//! Xác minh Cargo.lock và ghi projection tương thích theo cách atomic.

use mgc_types::{MgError, MgResult};
use std::path::Path;

const CARGO_LOCK_HEADER: &str =
    "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n";

/// Names of every dependency declared in the manifest, for diagnostics.
/// Tên mọi dependency đã khai trong manifest, dùng cho chẩn đoán.
fn declared_dependency_names(manifest: &toml::Value) -> String {
    let mut names: Vec<&str> = ["dependencies", "dev-dependencies", "build-dependencies"]
        .iter()
        .filter_map(|section| manifest.get(*section).and_then(toml::Value::as_table))
        .flat_map(|dependencies| dependencies.keys().map(String::as_str))
        .collect();
    names.sort_unstable();
    names.dedup();
    if names.is_empty() {
        "none".to_string()
    } else {
        names.join(", ")
    }
}

/// Prepare Cargo's root-package lock only when MGC has proved the native Rust
/// graph empty. Workspaces and unresolved declarations stay unsupported, so
/// MGC never writes a partial provider lock that hides dependencies.
/// Chỉ chuẩn bị lock Cargo của package root khi graph Rust native của MGC rỗng.
/// Workspace hoặc khai báo chưa resolve vẫn bị từ chối để tránh lock thiếu dep.
pub(crate) fn prepare_empty_cargo_lock(
    project_root: &Path,
    lock_packages: &[mgc_lockfile::Package],
) -> MgResult<Option<Vec<u8>>> {
    if !lock_packages.is_empty() {
        return Err(MgError::Other(
            "cannot create an empty Cargo.lock while MGC resolved Rust packages".to_string(),
        ));
    }

    let manifest_path = project_root.join("Cargo.toml");
    let content = mgc_adapter_base::project_file::read_regular_text(&manifest_path, "Cargo.toml")?;
    let manifest: toml::Value = toml::from_str(&content)
        .map_err(|error| MgError::Other(format!("parse Cargo.toml for empty lock: {error}")))?;
    let package = manifest
        .get("package")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| {
            MgError::Other(
                "cannot create an empty Cargo.lock for a virtual workspace; install its members separately"
                    .to_string(),
            )
        })?;

    if package.contains_key("workspace") {
        return Err(MgError::Other(
            "cannot create an empty Cargo.lock for a package inheriting workspace metadata; install from a supported workspace root"
                .to_string(),
        ));
    }
    let mut workspace_has_members = false;
    if let Some(workspace) = manifest.get("workspace") {
        let workspace = workspace
            .as_table()
            .ok_or_else(|| MgError::Other("Cargo.toml [workspace] must be a table".to_string()))?;
        for key in ["members", "default-members"] {
            if let Some(value) = workspace.get(key) {
                let members = value.as_array().ok_or_else(|| {
                    MgError::Other(format!("Cargo.toml workspace.{key} must be an array"))
                })?;
                workspace_has_members |= !members.is_empty();
            }
        }
    }
    if workspace_has_members {
        return Err(MgError::Other(
            "cannot create an empty Cargo.lock for a workspace with members; install each member through a workspace-aware resolver"
                .to_string(),
        ));
    }

    let has_dependencies = ["dependencies", "dev-dependencies", "build-dependencies"]
        .iter()
        .any(|section| {
            manifest
                .get(*section)
                .and_then(toml::Value::as_table)
                .is_some_and(|dependencies| !dependencies.is_empty())
        })
        || manifest
            .get("target")
            .and_then(toml::Value::as_table)
            .is_some_and(|targets| {
                targets.values().any(|target| {
                    ["dependencies", "dev-dependencies", "build-dependencies"]
                        .iter()
                        .any(|section| {
                            target
                                .get(*section)
                                .and_then(toml::Value::as_table)
                                .is_some_and(|dependencies| !dependencies.is_empty())
                        })
                })
            });
    if has_dependencies {
        // Never write a lock that hides declared dependencies, but say what
        // the empty graph usually means: a feature-gated dependency with no
        // feature enabled (`esp-hal` without its chip feature) has no real
        // dependency for MGC to resolve. Guidance keeps the failure honest
        // instead of only restating it.
        // (Không bao giờ ghi lock che giấu dependency đã khai, nhưng nêu ý nghĩa
        // của graph rỗng: dependency sau feature mà không bật feature nào
        // (`esp-hal` thiếu chip feature) không có dependency thật để resolve.)
        let declared = declared_dependency_names(&manifest);
        return Err(MgError::Other(format!(
            "Cargo.toml declares dependencies but MGC resolved an empty Rust graph; refusing to write an empty Cargo.lock. Declared: {declared}. A feature-gated dependency with no feature enabled (for example `esp-hal` without its chip feature `features = [\"esp32c3\"]`) really has no dependency graph — enable the feature that matches the target, or remove the unused declaration"
        )));
    }

    let name = package
        .get("name")
        .and_then(toml::Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| MgError::Other("Cargo.toml package.name is required".to_string()))?;
    let version = package
        .get("version")
        .and_then(toml::Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| MgError::Other("Cargo.toml package.version is required".to_string()))?;
    mgc_types::Version::parse(version).map_err(|error| {
        MgError::Other(format!(
            "Cargo.toml package.version '{version}' is invalid: {error}"
        ))
    })?;

    let mut package_entry = toml::map::Map::new();
    package_entry.insert("name".to_string(), toml::Value::String(name.to_string()));
    package_entry.insert(
        "version".to_string(),
        toml::Value::String(version.to_string()),
    );
    let mut document = toml::map::Map::new();
    document.insert("version".to_string(), toml::Value::Integer(4));
    document.insert(
        "package".to_string(),
        toml::Value::Array(vec![toml::Value::Table(package_entry)]),
    );
    let serialized = toml::to_string(&toml::Value::Table(document))
        .map_err(|error| MgError::Other(format!("serialize empty Cargo.lock: {error}")))?;
    let mut bytes = CARGO_LOCK_HEADER.as_bytes().to_vec();
    bytes.extend_from_slice(serialized.as_bytes());

    let lock_path = project_root.join("Cargo.lock");
    let existing = match std::fs::symlink_metadata(&lock_path) {
        Ok(metadata) if metadata.file_type().is_file() => Some(
            mgc_adapter_base::project_file::read_regular_text(&lock_path, "Cargo.lock")?
                .into_bytes(),
        ),
        Ok(_) => {
            return Err(MgError::Other(
                "refusing non-regular or symlink Cargo.lock".to_string(),
            ));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => {
            return Err(MgError::Other(format!("inspect Cargo.lock: {error}")));
        }
    };
    if existing.as_deref() == Some(bytes.as_slice()) {
        return Ok(None);
    }
    let signature_path = mgc_lockfile::parser::signature_path_for(&lock_path);
    match std::fs::symlink_metadata(&signature_path) {
        Ok(_) => {
            return Err(MgError::Other(format!(
                "refusing to replace Cargo.lock while signature sidecar '{}' exists",
                signature_path.display()
            )));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(MgError::Other(format!(
                "cannot inspect Cargo.lock signature sidecar '{}': {error}",
                signature_path.display()
            )));
        }
    }
    Ok(Some(bytes))
}
